package sfz.bigdata.l03.demo

import java.io.File
import java.sql.Connection
import java.sql.DriverManager

/**
 * A "table" that is only a directory of files plus a schema. Adding a file adds rows, and a bad
 * file is only noticed when a query reads it.
 */
fun main() {
    val dir = File("build/l03/raw/payments").apply { deleteRecursively(); mkdirs() }
    DriverManager.getConnection("jdbc:duckdb:").use { c ->
        // two batches land as files; nobody runs INSERT
        batch(c, File(dir, "batch-1.parquet"), from = 0)
        batch(c, File(dir, "batch-2.parquet"), from = 1_000)
        c.run("CREATE VIEW payments AS SELECT * FROM read_parquet('${dir.absolutePath}/*.parquet')")
        println("2 files:  " + c.query("SELECT count(*), sum(amount_cents) FROM payments"))

        batch(c, File(dir, "batch-3.parquet"), from = 2_000)
        println("3 files:  " + c.query("SELECT count(*), sum(amount_cents) FROM payments"))

        // an upstream job changes amount_cents to text like '12.50 EUR'; writing the file works fine
        c.run("COPY (SELECT 3000 AS payment_id, '12.50 EUR' AS amount_cents) TO '${File(dir, "batch-4.parquet").absolutePath}' (FORMAT parquet)")
        println("4 files:  " + runCatching { c.query("SELECT count(*), sum(amount_cents) FROM payments") }
            .getOrElse { "query failed: " + it.message!!.lineSequence().first() })
    }
}

private fun batch(c: Connection, file: File, from: Int) =
    c.run("COPY (SELECT i AS payment_id, (i % 997) * 100 AS amount_cents FROM range($from, ${from + 1_000}) t(i)) TO '${file.absolutePath}' (FORMAT parquet)")

private fun Connection.run(sql: String) = createStatement().use { it.execute(sql) }

private fun Connection.query(sql: String): String = createStatement().use { s ->
    s.executeQuery(sql).use { rs -> rs.next(); (1..rs.metaData.columnCount).joinToString(", ") { "${rs.metaData.getColumnLabel(it)} = ${rs.getString(it)}" } }
}

package sfz.bigdata.l03.demo

import org.apache.spark.sql.SaveMode
import java.io.File
import java.sql.DriverManager

/**
 * Spark writes a week of payments as a Hive-style table, one directory per day.
 * Then DuckDB plans two queries for the same day and says how many files each would open.
 */
fun main() {
    val lake = File("build/l03/lake")
    val spark = demoSpark()
    demoPayments(spark).write().mode(SaveMode.Overwrite).partitionBy("dt").parquet(lake.absolutePath)
    spark.stop()

    val files = dataFiles(lake)
    println("%d files in %d directories, for example:".format(files.size, lake.listFiles { f -> f.isDirectory }!!.size))
    files.take(3).forEach { println("  $it") }

    val scan = "read_parquet('${lake.absolutePath}/**/*.parquet', hive_partitioning = true)"
    DriverManager.getConnection("jdbc:duckdb:").use { c ->
        for (where in listOf("dt = '2026-11-03'", "created_at::DATE = DATE '2026-11-03'")) {
            val sql = "SELECT sum(amount_cents) FROM $scan WHERE $where"
            val plan = c.createStatement().use { s -> s.executeQuery("EXPLAIN $sql").use { rs -> rs.next(); rs.getString(2) } }
            // DuckDB prints "Scanning Files: n/total" only when it can skip files by their path
            val scanning = Regex("""Scanning Files: (\d+/\d+)""").find(plan)?.groupValues?.get(1) ?: "all ${files.size}"
            println("WHERE %-38s -> opens %s files".format(where, scanning))
        }
    }
}

package sfz.bigdata.l03.demo

import java.io.File
import java.sql.Connection
import java.sql.DriverManager

/** The same week of payments stored as 7 files and as 350 small ones, then queried the same way. */
fun main() {
    DriverManager.getConnection("jdbc:duckdb:").use { c ->
        // 70,000 payments, 10,000 a day for 7 days
        c.run("""CREATE TABLE payments AS
                 SELECT i AS payment_id, (hash(i) % 250000 + 100)::BIGINT AS amount_cents,
                        DATE '2026-11-01' + (i // 10000)::INTEGER AS dt
                 FROM range(70000) t(i)""")
        val few = fresh("build/l03/few-files")
        val many = fresh("build/l03/many-files")
        for (day in 0 until 7) {
            val dt = "2026-11-0${day + 1}"
            // one file per day, as a daily batch job would write it
            c.copy("SELECT payment_id, amount_cents FROM payments WHERE dt = DATE '$dt'", File(few, "dt=$dt/part-0.parquet"))
            // 50 files per day, as a job with 50 tasks (or a stream writing every half hour) would
            for (part in 0 until 50) {
                c.copy("SELECT payment_id, amount_cents FROM payments WHERE dt = DATE '$dt' AND payment_id % 50 = $part",
                    File(many, "dt=$dt/part-$part.parquet"))
            }
        }
        for (root in listOf(few, many)) {
            val sql = "SELECT dt, sum(amount_cents) FROM read_parquet('${root.absolutePath}/**/*.parquet') GROUP BY dt"
            val best = (1..5).minOf {
                val t0 = System.nanoTime()
                c.createStatement().use { s -> s.executeQuery(sql).use { rs -> while (rs.next()) Unit } }
                (System.nanoTime() - t0) / 1e6
            }
            val files = root.walkTopDown().filter { it.name.endsWith(".parquet") }.toList()
            println("%-10s %4d files, %4.1f MB, query %5.1f ms".format(root.name, files.size, files.sumOf { it.length() } / 1e6, best))
        }
    }
}

private fun fresh(path: String) = File(path).apply { deleteRecursively(); mkdirs() }

private fun Connection.run(sql: String) = createStatement().use { it.execute(sql) }

private fun Connection.copy(select: String, file: File) {
    file.parentFile.mkdirs()
    run("COPY ($select) TO '${file.absolutePath}' (FORMAT parquet)")
}

