CREATE EXTERNAL TABLE payments (
  payment_id   BIGINT,
  amount_cents BIGINT,
  created_at   TIMESTAMP
)
PARTITIONED BY (dt STRING)
STORED AS PARQUET
LOCATION 's3a://lake/payments/';

-- a job copies batch-4.parquet into s3a://lake/payments/dt=2026-11-08/; nothing checks it
ALTER TABLE payments ADD PARTITION (dt = '2026-11-08');
SELECT sum(amount_cents) FROM payments WHERE dt = '2026-11-08';
-- only now does a reader hit the file whose amount_cents is a string

